import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Item Source","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/corelib/item-source.md","filePath":"en/modules/corelib/item-source.md","lastUpdated":0}`),a={name:`en/modules/corelib/item-source.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="item-source" tabindex="-1">Item Source <a class="header-anchor" href="#item-source" aria-label="Permalink to “Item Source”">​</a></h1><p>CoreLib Item Source provides a stable way to identify items from Vanilla and external item ecosystems. It is better than relying on display names or lore.</p><h2 id="supported-sources" tabindex="-1">Supported sources <a class="header-anchor" href="#supported-sources" aria-label="Permalink to “Supported sources”">​</a></h2><p><code>ItemSourceKind</code> is a record rather than an enum, written <code>namespace:id</code>. A blank namespace becomes <code>emaki</code>. That design is deliberate: it lets a third-party plugin mint its own source kind. Whoever supplies the <code>ItemSourceProvider</code> declares the kind and its dash-shorthand prefixes in the same registration, using its own namespace.</p><p>The eight built-in constants CoreLib implements itself all live in the <code>emaki</code> namespace:</p><table tabindex="0"><thead><tr><th>Constant</th><th>Kind key</th><th>Aliases</th></tr></thead><tbody><tr><td><code>VANILLA</code></td><td><code>emaki:vanilla</code></td><td><code>vanilla</code>, <code>minecraft</code>, <code>v</code></td></tr><tr><td><code>CRAFTENGINE</code></td><td><code>emaki:craftengine</code></td><td><code>craftengine</code>, <code>ce</code></td></tr><tr><td><code>ITEMSADDER</code></td><td><code>emaki:itemsadder</code></td><td><code>itemsadder</code>, <code>ia</code></td></tr><tr><td><code>NEIGEITEMS</code></td><td><code>emaki:neigeitems</code></td><td><code>neigeitems</code>, <code>ni</code></td></tr><tr><td><code>MMOITEMS</code></td><td><code>emaki:mmoitems</code></td><td><code>mmoitems</code>, <code>mi</code></td></tr><tr><td><code>NEXO</code></td><td><code>emaki:nexo</code></td><td><code>nexo</code>, <code>no</code></td></tr><tr><td><code>ORAXEN</code></td><td><code>emaki:oraxen</code></td><td><code>oraxen</code>, <code>ox</code></td></tr><tr><td><code>ECOITEMS</code></td><td><code>emaki:ecoitems</code></td><td><code>ecoitems</code>, <code>eco</code>, <code>eci</code></td></tr></tbody></table><p>There is deliberately <strong>no</strong> <code>EMAKIITEM</code> constant: its resolver lives in the EmakiItem module, so its kind and prefixes are declared there as <code>ItemSourceKind.of(&quot;emakiitem:emakiitem&quot;)</code>, with <code>emakiitem</code> and <code>ei</code> as config aliases.</p><p>Type names are case-insensitive. The available sources at runtime depend on which plugins are installed.</p><p>Type aliases and dash-shorthand prefixes are not identical: the <code>type:</code> field accepts every alias above, while the dash shorthand accepts <code>minecraft-</code>, <code>mc-</code>, <code>v-</code>, <code>craftengine-</code>, <code>ce-</code>, <code>itemsadder-</code>, <code>ia-</code>, <code>neigeitems-</code>, <code>ni-</code>, <code>mmoitems-</code>, <code>mi-</code>, <code>emakiitem-</code>, <code>ei-</code>, <code>nexo-</code>, <code>no-</code>, <code>oraxen-</code>, <code>ox-</code>, <code>ecoitems-</code>, and <code>eci-</code> (there is no <code>eco-</code> shorthand).</p><h2 id="object-format" tabindex="-1">Object format <a class="header-anchor" href="#object-format" aria-label="Permalink to “Object format”">​</a></h2><p>The object format uses <code>type</code> plus <code>identifier</code>; both must be non-blank:</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">item</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">vanilla</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  identifier</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">diamond</span></span></code></pre></div><p>MMOItems requires a <code>&lt;type&gt;:&lt;item&gt;</code> identifier:</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">item</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mmoitems</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  identifier</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">SWORD:FLAME_SWORD</span></span></code></pre></div><p>When resolving an object node, CoreLib checks <code>item_sources</code> first, then the string field <code>item</code> (parsed as dash shorthand), then a nested <code>source</code>, and only then falls back to <code>type</code> + <code>identifier</code>.</p><p>Vanilla identifiers are normalised to lowercase and may only contain lowercase letters, digits, and underscores; a <code>minecraft:</code> namespace prefix is rejected.</p><h2 id="resolution-priority" tabindex="-1">Resolution priority <a class="header-anchor" href="#resolution-priority" aria-label="Permalink to “Resolution priority”">​</a></h2><p>When several plugins can identify the same item, CoreLib tries resolvers in descending <code>priority</code>, breaking ties by resolver ID:</p><table tabindex="0"><thead><tr><th>Resolver</th><th>priority</th></tr></thead><tbody><tr><td>NeigeItems</td><td><code>102</code></td></tr><tr><td>CraftEngine</td><td><code>101</code></td></tr><tr><td>MMOItems</td><td><code>100</code></td></tr><tr><td>EmakiItem (registered by EmakiItem)</td><td><code>100</code></td></tr><tr><td>ItemsAdder</td><td><code>98</code></td></tr><tr><td>Nexo</td><td><code>97</code></td></tr><tr><td>Oraxen</td><td><code>96</code></td></tr><tr><td>EcoItems</td><td><code>95</code></td></tr><tr><td>Vanilla (fallback)</td><td><code>0</code></td></tr></tbody></table><h2 id="unified-item-definitions" tabindex="-1">Unified item definitions <a class="header-anchor" href="#unified-item-definitions" aria-label="Permalink to “Unified item definitions”">​</a></h2><p>CoreLib GUI slots and EmakiItem base items share <code>ConfiguredItemDefinition</code>. In YAML the source lives at <code>item.source</code>:</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">item</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  source</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">itemsadder-custom_items:ruby_sword</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  amount</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  components</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    custom_name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;red&gt;Ruby Sword&lt;/red&gt;&#39;</span></span></code></pre></div><p><code>item.source</code> accepts every ItemSource shorthand currently registered in CoreLib. EmakiItem validates that the resolver is available and can create the base item before caching a definition. For third-party sources, component application preserves source identity, PDC, and unknown components, and transfers only patches that the current Paper runtime can safely handle.</p><h2 id="finding-the-id-for-each-source" tabindex="-1">Finding the ID for each source <a class="header-anchor" href="#finding-the-id-for-each-source" aria-label="Permalink to “Finding the ID for each source”">​</a></h2><h3 id="vanilla" tabindex="-1">Vanilla <a class="header-anchor" href="#vanilla" aria-label="Permalink to “Vanilla”">​</a></h3><p>Use the Bukkit <code>Material</code> enum name with underscores. Identifiers are normalised to lowercase, so either case is accepted as input:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>diamond_sword, iron_chestplate, golden_apple, netherite_axe</span></span></code></pre></div><p>The dash shorthand accepts <code>minecraft-</code>, <code>mc-</code>, and <code>v-</code>. See the <a href="https://hub.spigotmc.org/javadocs/spigot/org/bukkit/Material.html" target="_blank" rel="noreferrer">Spigot Material docs</a> for the full list.</p><h3 id="emakiitem" tabindex="-1">EmakiItem <a class="header-anchor" href="#emakiitem" aria-label="Permalink to “EmakiItem”">​</a></h3><p>Use the <code>id</code> field defined in <code>plugins/EmakiItem/items/*.yml</code>:</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># items/flame_blade.yml</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">flame_blade</span></span></code></pre></div><p>Reference it as the shorthand <code>emakiitem-flame_blade</code>, or in object form as <code>type: emakiitem</code> plus <code>identifier: flame_blade</code>.</p><h3 id="craftengine" tabindex="-1">CraftEngine <a class="header-anchor" href="#craftengine" aria-label="Permalink to “CraftEngine”">​</a></h3><p>Use the item ID registered with CraftEngine, which its own commands can list.</p><h3 id="itemsadder" tabindex="-1">ItemsAdder <a class="header-anchor" href="#itemsadder" aria-label="Permalink to “ItemsAdder”">​</a></h3><p>Use the ItemsAdder namespaced ID, usually <code>namespace:item_id</code>:</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">item</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">itemsadder</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  identifier</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">custom_items:ruby_sword</span></span></code></pre></div><h3 id="nexo" tabindex="-1">Nexo <a class="header-anchor" href="#nexo" aria-label="Permalink to “Nexo”">​</a></h3><p>Use the item ID registered with Nexo.</p><h3 id="mmoitems" tabindex="-1">MMOItems <a class="header-anchor" href="#mmoitems" aria-label="Permalink to “MMOItems”">​</a></h3><p>Give both the item type and the ID in <code>identifier</code>, separated by a colon:</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">item</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mmoitems</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  identifier</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">SWORD:FLAME_SWORD</span></span></code></pre></div><h3 id="neigeitems" tabindex="-1">NeigeItems <a class="header-anchor" href="#neigeitems" aria-label="Permalink to “NeigeItems”">​</a></h3><p>Use the item ID from the NeigeItems configuration.</p><h2 id="why-not-to-rely-on-display-names" tabindex="-1">Why not to rely on display names <a class="header-anchor" href="#why-not-to-rely-on-display-names" aria-label="Permalink to “Why not to rely on display names”">​</a></h2><ul><li>A display name can be changed by an anvil, a plugin, or the language system.</li><li>Lore may be rebuilt by the Attribute, Forge, Strengthen, or Gem modules.</li><li>Colour codes, MiniMessage, and legacy colour symbols make text inconsistent.</li><li>Players may obtain a similarly named item some other way.</li><li>A display name can change on update while the ID stays stable.</li></ul><h2 id="advice" tabindex="-1">Advice <a class="header-anchor" href="#advice" aria-label="Permalink to “Advice”">​</a></h2><p>Use stable IDs for recipe materials, rewards, conditions, and station matching. Avoid judging items by display name or lore because they may be modified by other plugins or rebuilt by CoreLib Assembly.</p><p>CraftEngine, ItemsAdder, and Nexo item sources can also be passed to the <code>place_block</code> action when the source represents a custom block.</p>`,49)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};